 "content": "def transform(grid):
    colors = sorted({value for row in grid for value in row})
    remap = {colors[0]: 0}
    for i in range(1, len(colors)):
        remap[colors[i]] = colors[i - 1]
    return [[remap[value] for value in row] for row in grid]
